import { promises as fs } from 'node:fs';for(const p of ['scripts/build.mjs','assets/atlas.css'])await fs.access(p).catch(()=>{throw new Error(`Eksik: ${p}`)});let b=await fs.readFile('scripts/build.mjs','utf8');if(!b.includes('V25.1 Cinematic Research Compass')){b+='\n'+await fs.readFile('v25-1-build-patch.txt','utf8');await fs.writeFile('scripts/build.mjs',b)}let c=await fs.readFile('assets/atlas.css','utf8');if(!c.includes('V25.1 Cinematic Research Compass')){c+='\n'+await fs.readFile('v25-1-css-patch.txt','utf8');await fs.writeFile('assets/atlas.css',c)}await fs.copyFile('research-compass.js','assets/research-compass.js');console.log('V25.1 kuruldu: sinematik, hareketli ve veri güdümlü Araştırma Pusulası eklendi.');
